// ============================================================================
// FAO HITL Notifier (fao_hitl_gateway_v1) - Validate Payload
// ----------------------------------------------------------------------------
// FAO-GOV-007: the notifier input is exactly {hitl_id, kind, level}:
//   kind REQUESTED with level 0 (first notice of a new request), or
//   kind ESCALATED with level 1 (escalation to the process owner's target).
// Nothing else is read. Request content, approver names, the approval link
// and the Slack settings all come from fao_notification_context, so a caller
// cannot change what is posted or where it links.
// ============================================================================

const items = $input.all();
if (items.length !== 1) {
  throw new Error('FAO-GOV-007 notifier: payload invalid (expected exactly one item)');
}

const input = (items[0] && items[0].json) || {};
const hitl_id = input.hitl_id;
const kind = input.kind;
const level = input.level;

if (!Number.isSafeInteger(hitl_id) || hitl_id < 1) {
  throw new Error('FAO-GOV-007 notifier: hitl_id invalid');
}
if (kind !== 'REQUESTED' && kind !== 'ESCALATED') {
  throw new Error('FAO-GOV-007 notifier: kind invalid');
}
const expected_level = kind === 'REQUESTED' ? 0 : 1;
if (level !== expected_level) {
  throw new Error('FAO-GOV-007 notifier: level invalid');
}

return [{ json: { hitl_id, kind, level } }];

// ============================================================================
// FAO HITL Notifier - Compose Slack Message
// ----------------------------------------------------------------------------
// FAO-GOV-004 / FAO-GOV-007: builds the Slack chat.postMessage request from
// the fao_notification_context result only.
//   - One link: r.approval_url, the approval page for this request. The page
//     signs the approver in and records the decision through fao_hitl_decide
//     with the approver's own session; the link carries no identity and no
//     decision.
//   - REQUESTED names the eligible approvers from r.approver_candidates (the
//     database excludes the invoker). ESCALATED names r.target_name, or says
//     "none eligible (operator alerted)" when the database found no target
//     (IC-13: the sweep raises FAO-GOV-008 for the operator then).
//   - ESCALATED after the deadline (a TIMEOUT escalation: the sweep has
//     already expired the request and closed the run) says the request
//     expired without a decision and asks for no decision; fao_hitl_decide
//     refuses one with EXPIRED. The deadline is compared with this host's
//     clock, which matches the database clock outside local tests.
//   - Every dynamic value passes slackEscape() so stored text cannot form
//     Slack markup, mentions or extra links.
//   - The API URL is r.slack_api_base_url + '/chat.postMessage', so the same
//     export posts to Slack live and to a local mock in tests.
//   - FAO-GOV-007: an unusable Slack or approval-page setting does not throw.
//     The node emits {compose_ok: false, compose_error}; Compose OK? sends it
//     straight to Classify Slack Result, and Record Notification stores a
//     FAILED attempt, so the sweep's notify_max_attempts count and the
//     NOTIFICATION_FAILED escalation see it like a Slack failure.
// ============================================================================

const r = (($input.first() || {}).json || {}).r;
if (!r || typeof r !== 'object' || r.ok !== true || r.send !== true) {
  throw new Error('FAO-GOV-007 notifier: notification context is not sendable');
}
if (r.kind !== 'REQUESTED' && r.kind !== 'ESCALATED') {
  throw new Error('FAO-GOV-007 notifier: kind invalid');
}

const kind = r.kind;
const level = r.level;
const hitl_id = r.hitl_id;

function slackEscape(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Settings problems become a recorded FAILED attempt, not a thrown error.
const HTTP_URL = /^https?:\/\/[^\s<>|]+$/;
const setting_problems = [];
if (typeof r.approval_url !== 'string' || !HTTP_URL.test(r.approval_url)) {
  setting_problems.push('approval_url invalid');
}
if (typeof r.slack_api_base_url !== 'string' || !HTTP_URL.test(r.slack_api_base_url)) {
  setting_problems.push('slack_api_base_url invalid');
}
if (typeof r.slack_channel_id !== 'string' || r.slack_channel_id === '') {
  setting_problems.push('slack_channel_id invalid');
}
if (setting_problems.length > 0) {
  return [{
    json: {
      hitl_id,
      kind,
      level,
      compose_ok: false,
      compose_error: `FAO-GOV-007 notifier: ${setting_problems.join('; ')}`
    }
  }];
}

// Escalated assets: objects {asset, policy_outcome, policy_sub_tier,
// band_status} from the rollup, or plain symbols.
const assets = Array.isArray(r.escalated_assets) ? r.escalated_assets : [];
const asset_text = assets.length === 0
  ? '(none listed)'
  : assets.map(a => {
      if (a !== null && typeof a === 'object') {
        const parts = [a.policy_outcome, a.policy_sub_tier]
          .filter(p => p !== null && p !== undefined && p !== '');
        return slackEscape(a.asset) + (parts.length ? ' (' + parts.map(slackEscape).join('/') + ')' : '');
      }
      return slackEscape(a);
    }).join(', ');

const candidates = Array.isArray(r.approver_candidates) ? r.approver_candidates : [];
const candidate_text = candidates.length === 0
  ? '(no eligible approver found)'
  : candidates.map(c => slackEscape(c && typeof c === 'object' ? c.name : c)).join(', ');

const target_text = (typeof r.target_name === 'string' && r.target_name.trim() !== '')
  ? slackEscape(r.target_name)
  : 'none eligible (operator alerted)';

const deadline_ms = Date.parse(r.timeout_at);
const expired = kind === 'ESCALATED' && Number.isFinite(deadline_ms) && deadline_ms <= Date.now();

const agent_label = slackEscape(r.agent_name || r.agent_id);
let header;
if (kind === 'REQUESTED') {
  header = `*Approval required: request ${slackEscape(hitl_id)} for ${agent_label}*`;
} else if (expired) {
  header = `*Escalation: approval request ${slackEscape(hitl_id)} for ${agent_label} expired without a decision*`;
} else {
  header = `*Escalation: approval request ${slackEscape(hitl_id)} for ${agent_label} needs attention*`;
}

const lines = [
  header,
  '',
  `*Agent:* ${slackEscape(r.agent_id)}`,
  `*Risk tier:* ${slackEscape(r.risk_tier)}`,
  `*Review sub-tier:* ${slackEscape(r.sub_tier)}`,
  expired ? `*Deadline passed:* ${slackEscape(r.timeout_at)}` : `*Decide by:* ${slackEscape(r.timeout_at)}`,
  `*Escalated assets:* ${asset_text}`
];

if (kind === 'ESCALATED') {
  lines.push(`*Escalation target:* ${target_text}`);
} else {
  lines.push(`*Eligible approvers:* ${candidate_text}`);
}

if (expired) {
  lines.push(
    '',
    `<${slackEscape(r.approval_url)}|View the expired request>`,
    '',
    '_No decision can be recorded now: the request expired unanswered and the run was closed with status FAILURE. Please review why it was not decided in time._'
  );
} else {
  lines.push(
    '',
    `<${slackEscape(r.approval_url)}|Open the approval page>`,
    '',
    '_Sign in on the approval page to approve or reject. The person who started the run cannot decide it._'
  );
}

const text = lines.join('\n');
const url = r.slack_api_base_url.replace(/\/+$/, '') + '/chat.postMessage';

return [{
  json: {
    hitl_id,
    kind,
    level,
    compose_ok: true,
    url,
    body: { channel: r.slack_channel_id, text, mrkdwn: true }
  }
}];

// ============================================================================
// FAO HITL Notifier - Classify Slack Result
// ----------------------------------------------------------------------------
// FAO-GOV-007: both outputs of Slack: Post Message (success and error) and
// the false branch of Compose OK? feed this node. The attempt counts as SENT
// only when Slack answered HTTP 200 with body.ok === true; anything else
// (unusable setting, HTTP error, timeout, ok:false) is FAILED, recorded by
// Record Notification, and retried by the sweep.
// The HTTP status of an error item is read from error.httpCode, status or
// statusCode, then from error.cause (n8n 2.x puts "500 - <body>" in
// cause.message and Slack's error code in description).
// The ids come from Validate Payload, never from the HTTP response.
// ============================================================================

const ids = $('Validate Payload').first().json;
const res = (($input.first() || {}).json) || {};

const clean = (s) => String(s).replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, 300);

const STATUS = /^\s*(\d{3})\b/;
function statusOf(e) {
  if (!e || typeof e !== 'object') return undefined;
  const sources = [e, e.cause && typeof e.cause === 'object' ? e.cause : null];
  for (const s of sources) {
    if (!s) continue;
    for (const k of ['httpCode', 'status', 'statusCode']) {
      const v = s[k];
      if ((typeof v === 'number' && Number.isInteger(v)) || (typeof v === 'string' && /^\d{3}$/.test(v))) return String(v);
    }
  }
  for (const s of sources) {
    if (s && typeof s.message === 'string') {
      const m = STATUS.exec(s.message);
      if (m) return m[1];
    }
  }
  return undefined;
}

// Slack's own error code from a "500 - <body>" message, where the body may be
// JSON or a JSON-encoded string of JSON.
function slackErrorIn(text) {
  if (typeof text !== 'string') return null;
  const i = text.indexOf(' - ');
  if (i < 0) return null;
  let body = text.slice(i + 3);
  for (let n = 0; n < 2 && typeof body === 'string'; n += 1) {
    try { body = JSON.parse(body); } catch (err) { return null; }
  }
  return body && typeof body === 'object' && typeof body.error === 'string' ? body.error : null;
}

let outcome = 'FAILED';
let external_ref = null;
let error = null;

if (res.compose_ok === false) {
  // Compose OK? false branch: a setting made the message unsendable.
  error = `compose error: ${typeof res.compose_error === 'string' ? res.compose_error : 'unknown'}`;
} else if (res.error !== undefined && res.error !== null && res.statusCode === undefined) {
  // Error output of the HTTP Request node (network error, timeout, 4xx, 5xx).
  const e = res.error;
  let msg;
  if (typeof e === 'string') msg = e;
  else if (e && typeof e === 'object') msg = e.message || e.description || e.code || 'request failed';
  else msg = 'request failed';
  let detail = null;
  if (e && typeof e === 'object') {
    if (typeof e.description === 'string' && e.description !== '' && e.description !== msg) detail = e.description;
    else detail = slackErrorIn(e.cause && typeof e.cause === 'object' ? e.cause.message : null) || slackErrorIn(e.message);
  }
  const code = statusOf(e);
  error = (code !== undefined ? `http error ${code}: ${msg}` : `http error: ${msg}`) + (detail ? ` (${detail})` : '');
} else if (res.statusCode !== undefined || res.body !== undefined) {
  let body = res.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (err) { body = null; }
  }
  const status = res.statusCode;
  if (status === 200 && body !== null && typeof body === 'object' && body.ok === true) {
    outcome = 'SENT';
    external_ref = typeof body.ts === 'string' ? body.ts : null;
  } else {
    const slack_error = body !== null && typeof body === 'object' && typeof body.error === 'string'
      ? body.error : 'not ok';
    error = `slack status ${status}: ${slack_error}`;
  }
} else {
  error = 'no response from Slack';
}

return [{
  json: {
    hitl_id: ids.hitl_id,
    kind: ids.kind,
    level: ids.level,
    outcome,
    external_ref: external_ref === null ? null : clean(external_ref).slice(0, 200),
    error: error === null ? null : clean(error)
  }
}];
